const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set');

const item = $input.first().json;
const header = String(item.headers['x-lendloop-signature'] || '');
const parts = Object.fromEntries(header.split(',').map((p) => {
  const i = p.indexOf('=');
  return [p.slice(0, i).trim(), p.slice(i + 1).trim()];
}));
const t = Number(parts.t);
const now = Math.floor(Date.now() / 1000);
const raw = JSON.stringify(item.body);

let valid = Number.isInteger(t) && Math.abs(now - t) <= 300 && typeof parts.v1 === 'string';
if (valid) {
  const expected = crypto.createHmac('sha256', secret).update(t + '.' + raw).digest('hex');
  valid = expected.length === parts.v1.length &&
    crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(parts.v1));
}
if (!valid) return [{ json: { valid: false } }];

const e = item.body;
return [{
  json: {
    valid: true,
    eventId: e.eventId,
    type: e.type,
    recipientEmail: e.recipient && e.recipient.email,
    recipientFirstName: (e.recipient && e.recipient.firstName) || 'there',
    toolName: e.toolName,
    startDate: e.startDate,
    endDate: e.endDate,
  },
}];

const copy = {
  request_created: (e) => ['New request for your ' + e.toolName, 'Hi ' + e.recipientFirstName + ', a neighbour would like to borrow your ' + e.toolName + ' from ' + e.startDate + ' to ' + e.endDate + '. Open LendLoop to approve or decline.'],
  request_approved: (e) => ['Your request was approved', 'Hi ' + e.recipientFirstName + ', your request to borrow the ' + e.toolName + ' (' + e.startDate + ' to ' + e.endDate + ') was approved.'],
  request_declined: (e) => ['Your request was declined', 'Hi ' + e.recipientFirstName + ', your request to borrow the ' + e.toolName + ' was declined this time.'],
  request_cancelled: (e) => ['A request was cancelled', 'Hi ' + e.recipientFirstName + ', the request for the ' + e.toolName + ' (' + e.startDate + ' to ' + e.endDate + ') was cancelled.'],
  loan_returned: (e) => ['Loan marked returned', 'Hi ' + e.recipientFirstName + ', the ' + e.toolName + ' has been marked as returned. Thanks for using LendLoop!'],
};
return $input.all().map(({ json: e }) => {
  const build = copy[e.type];
  if (!build) throw new Error('Unknown event type: ' + e.type);
  const [subject, text] = build(e);
  return { json: { eventId: e.eventId, to: e.recipientEmail, subject, text } };
});

return $input.all().map(({ json: m }) => {
  if (!m.to) throw new Error('Notification has no recipient');
  console.log('[LendLoop] notify ' + m.to + ' | ' + m.subject + ' | ' + m.text);
  return { json: { eventId: m.eventId, status: 'sent', channel: 'mock-log' } };
});

const crypto = require('crypto');
function sign(body) {
  const secret = $env.LENDLOOP_CALLBACK_SECRET;
  if (!secret) throw new Error('LENDLOOP_CALLBACK_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto.createHmac('sha256', secret).update(t + '.' + body).digest('hex');
  return 't=' + t + ',v1=' + v1;
}
return $input.all().map(({ json: r }) => {
  const body = JSON.stringify({ eventId: r.eventId, status: r.status, message: 'Delivered via ' + r.channel });
  return { json: { body, signature: sign(body) } };
});
